 assert_eq!(sqlite3_strlike(Some(b"a%"), Some(b"a"),0), SQLITE_MATCH);
 assert_eq!(
 sqlite3_strlike(Some(b"a%"), Some(b"bc"),0),
 SQLITE_NOWILDCARDMATCH
 );
}

