//11. sqlite3_strlike: `_`匹配单字符 — `a_`匹配 `ab` 但不匹配 `abc`
// ============================================================================
#[test]
fn strlike_underscore_matches_single() {
 assert_eq!(sqlite3_strlike(Some(b"a_"), Some(b"ab"),0), SQLITE_MATCH);
 assert_eq!(
